cssReset:
* { box-sizing: border-box; -webkit-text-size-adjust: none; }
body { margin: 0; padding: 0; }
table { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
img { -ms-interpolation-mode: bicubic; }
.only-mobile { display: none !important; visibility: hidden !important; }
@media only screen and (max-width: 480px) {
  .mobileWidth { max-width: 375px !important; width: 100% !important; }
  .paddingMobile { padding-right: 10px !important; padding-left: 10px !important; }
  .only-desktop { display: none !important; visibility: hidden !important; }
  .only-mobile { display: table-cell !important; visibility: visible !important; }
  .only-mobile-cell { display: table-cell !important; visibility: visible !important; }
  .responsiveImage { width: 100% !important; }
  .stack { display: block !important; width: 100% !important; }
  .txtRealign { text-align: center !important; }
}
